function validate([list1, a, b, list2]) {
  if (!Array.isArray(list1) || list1.length < 3 || list1.length > 10000) return 'list1 needs 3 to 10^4 nodes.';
  if (!Array.isArray(list2) || list2.length < 1 || list2.length > 10000) return 'list2 needs 1 to 10^4 nodes.';
  if ([...list1, ...list2].some(v => !Number.isSafeInteger(v))) return 'Node values are whole numbers.';
  if (!Number.isInteger(a) || !Number.isInteger(b)) return 'a and b are whole numbers.';
  if (a < 1 || a > b || b >= list1.length - 1) return 'Positions must satisfy 1 <= a <= b < list1.length - 1.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values1, a, b, values2] = input;
  const result = solve(kit.toList(values1), a, b, kit.toList(values2));
  if (result === undefined) throw new Error('The solution did not return a value.');
  // Walk the returned list; it can never be longer than both inputs together.
  const values = [];
  const limit = values1.length + values2.length;
  for (let node = result; node !== null; node = node.next) {
    if (typeof node !== 'object') throw new Error('Return the head node of the merged list.');
    if (values.length >= limit) throw new Error('The returned list is too long or contains a cycle.');
    values.push(node.val);
  }
  return values;
}

