function mergeInBetween(list1, a, b, list2) {
  // Copy both lists into arrays, assemble the answer's values, and build a brand-new list.
  const first = [];
  for (let node = list1; node; node = node.next) first.push(node.val);
  const second = [];
  for (let node = list2; node; node = node.next) second.push(node.val);
  const merged = [...first.slice(0, a), ...second, ...first.slice(b + 1)];
  let head = null;
  for (let k = merged.length - 1; k >= 0; k--) head = new ListNode(merged[k], head);
  return head;
}

