function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1800 + pick(201) : 3 + pick(7);
  const m = size === 'large' ? 1500 + pick(501) : 1 + pick(5);
  const span = size === 'large' || rand() < 0.4 ? 1000000 : 9;
  const values = k => Array.from({ length: k }, () => pick(span + 1));
  const a = 1 + pick(n - 2);
  const b = a + pick(n - 1 - a);
  return [values(n), a, b, values(m)];
}
